mapper.select:
SELECT REQUEST_ID, CHANGE_TYPE, BEFORE_STATUS, TARGET_STATUS, CURRENT_VERSION_NO, TARGET_VERSION_NO FROM MASTER_CHANGE_REQUEST_ITEM WHERE REQUEST_ID IN
#{requestId}
AND VALID_FLAG = '1' AND DEL_FLAG = '0' ORDER BY REQUEST_ID, ITEM_NO, ID

SELECT COALESCE(i.RESULT_MASTER_RECORD_ID, i.MASTER_RECORD_ID) AS RECORD_ID, r.ID AS REQUEST_ID, r.REQUEST_NO, r.STATUS, r.EXECUTE_STATUS, i.CHANGE_TYPE FROM MASTER_CHANGE_REQUEST_ITEM i INNER JOIN MASTER_CHANGE_REQUEST r ON r.ID = i.REQUEST_ID WHERE r.MODEL_ID = #{modelId} AND r.SUBMIT_TIME IS NOT NULL AND r.VALID_FLAG = '1' AND r.DEL_FLAG = '0' AND i.VALID_FLAG = '1' AND i.DEL_FLAG = '0' AND COALESCE(i.RESULT_MASTER_RECORD_ID, i.MASTER_RECORD_ID) IN
#{recordId}
ORDER BY CASE WHEN THEN 0 ELSE 1 END, COALESCE(r.SUBMIT_TIME, r.CREATE_TIME) DESC, r.ID DESC
